  mode(L) { const d = dataSet(rnd(6, 9), 1, L ? 15 : 9); return msQ('', `أوجدِ المنوالَ للبيانات: ${L2(d)} (اكتبْ «لا يوجد» إن لم يكنْ هناك منوال)`, d, ['mode']); },
  range(L) { const d = dataSet(rnd(5, 8), L ? 20 : 1, L === 2 ? 500 : L ? 99 : 30); return msQ('', `أوجدِ المدى للبيانات: ${L2(d)}`, d, ['range']); },
  mmr(L) { const n = rnd(5, 8); let d; for (let k = 0; k < 60; k++) { d = dataSet(n, 5, L ? 60 : 25); if (sum(d) % n === 0) break; } return msQ('', `أوجدِ المتوسّطَ الحسابيَّ والوسيطَ والمنوالَ والمدى للبيانات: ${L2(d)}`, d, ['mean', 'median', 'mode', 'range']); },
  outlier(L) { const n = rnd(4, 6); let d, o; for (let k = 0; k < 80; k++) { d = dataSet(n, 20, 40); o = pick([rnd(90, 150), rnd(1, 4)]); if ((sum(d) + o) % (n + 1) === 0 && sum(d) % n === 0) break; } const all = shuf([...d, o]); return fld('', `البيانات: ${L2(all)}. حدّدِ القيمةَ المتطرّفة، ثم أوجدِ المتوسّطَ الحسابيَّ مع وجودِها ومن دونِها.`, [['القيمةُ المتطرّفة', o], ['المتوسّطُ معها', Math.round(mean(all) * 100) / 100], ['المتوسّطُ من دونِها', Math.round(mean(d) * 100) / 100]], { sol: [`القيمةُ ${AR(o)} بعيدةٌ جدًّا عن بقيّةِ القيم.`, `معها: ${AR(sum(all))} ÷ ${AR(n + 1)} = ${fmt(Math.round(mean(all) * 100) / 100)}`, `من دونِها: ${AR(sum(d))} ÷ ${AR(n)} = ${fmt(Math.round(mean(d) * 100) / 100)}`], skill: 'outlier' }); },
  dotread(L) { const lo = rnd(1, 20), d = dataSet(rnd(10, 16), lo, lo + rnd(6, 10)), v = pick(d), c = counts(d); const q = pick(L === 0 ? ['eq'] : ['eq', 'ge', 'diff']); const ge = d.filter(x => x >= v).length;
    return num('', q === 'eq' ? `يبيّنُ التمثيلُ بالنقاط بياناتٍ. كم مرّةً تكرّرَ العدد ${AR(v)}؟` : q === 'ge' ? `يبيّنُ التمثيلُ بالنقاط بياناتٍ. كم قيمةً تساوي ${AR(v)} أو أكثر؟` : 'ما الفرقُ بينَ أكبرِ قيمةٍ وأصغرِ قيمةٍ في التمثيلِ بالنقاط؟', q === 'eq' ? c[v] : q === 'ge' ? ge : range(d), { html: dotSVG(d, { min: lo - 1, max: lo + 11 }), skill: 'dotread', sol: [q === 'eq' ? `عددُ إشاراتِ × فوقَ ${AR(v)} = ${AR(c[v])}` : q === 'ge' ? `نعدُّ الإشاراتِ فوقَ ${AR(v)} وما بعدَه: ${AR(ge)}` : `${AR(Math.max(...d))} − ${AR(Math.min(...d))} = ${AR(range(d))}`] }); },
  barread(L) { const it = shuf(['التفّاح', 'البرتقال', 'الموز', 'العنب', 'المانجو', 'الفراولة']).slice(0, rnd(4, 5)), st = L === 2 ? 5 : 2, d = it.map(n => [n, rnd(1, L === 2 ? 12 : 8) * st]); const [a, b] = shuf(d.slice()).slice(0, 2);
    return num('', `يبيّنُ التمثيلُ بالأعمدةِ الفاكهةَ المفضّلةَ لعددٍ من الطلاب. كم يزيدُ عددُ الذين يفضّلون ${a[1] >= b[1] ? a[0] : b[0]} على الذين يفضّلون ${a[1] >= b[1] ? b[0] : a[0]}؟`, Math.abs(a[1] - b[1]), { html: chartBox(d, { title: 'الفاكهةُ المفضّلة', step: st, labels: L === 0, y: 'عددُ الطلاب' }), skill: 'barread', sol: [`${AR(Math.max(a[1], b[1]))} − ${AR(Math.min(a[1], b[1]))} = ${AR(Math.abs(a[1] - b[1]))}`] }); },
  tally(L) { const K = { ح: 'أحمر', ز: 'أزرق', خ: 'أخضر', ص: 'أصفر' }, keys = Object.keys(K).slice(0, L ? 4 : 3), it = Array.from({ length: L === 2 ? 24 : 15 }, () => pick(keys)); const c = counts(it), [a, b] = shuf(keys).slice(0, 2);
    return fld('', `الألوانُ المفضّلة (${keys.map(k => `${k} = ${K[k]}`).join('، ')}): ${it.join('، ')}. كوّنْ جدولًا تكراريًّا، ثم أجبْ:`, [[`تكرارُ ${K[a]}`, c[a] || 0], [`كم يزيدُ ${K[a]} على ${K[b]}؟ (قد يكونُ سالبًا ← اكتبْ الفرقَ موجبًا)`, Math.abs((c[a] || 0) - (c[b] || 0))]], { skill: 'tally', sol: [keys.map(k => `${K[k]}: ${AR(c[k] || 0)}`).join('، ')], mount: el => { el.innerHTML = '<button class="lnk">📋 كوّنِ الجدولَ التكراريّ</button>'; $('button', el).onclick = () => tallyTool(el, { items: it, names: Object.fromEntries(keys.map(k => [k, K[k]])), head: 'اللون' }); } }); }
