  intro: [{ h: 'التمثيلُ بالأعمدة', p: 56, html: '<p><b>البيانات</b> هي معلوماتٌ تكونُ عدديّةً في الغالب، و<b>التمثيلُ البيانيّ</b> هو الطريقةُ الأنسبُ لعرضِها بصريًّا. يُستعملُ <b>التمثيلُ بالأعمدة</b> للمقارنةِ بينَ البياناتِ وتصنيفِها.</p>' + chartBox([['البريد الإلكتروني', 10], ['برامج الجوال', 12], ['رسائل الجوال', 4], ['الرسائل البريدية', 2]], { title: 'الوسيلةُ المفضّلةُ للاتّصال', step: 2, y: 'التكرار', x: 'وسيلةُ الاتّصال' }) + '<p>يُكتبُ <b>التدريجُ</b> على <b>المحورِ الرأسيّ</b>، ويتوزّعُ إلى أجزاءٍ متساويةٍ تُسمّى <b>فترات</b> (طولُ الفترةِ هنا ٢)، وتُسجَّلُ الأنواعُ على <b>المحورِ الأفقيّ</b>. ويمثّلُ ارتفاعُ كلِّ عمودٍ <b>تكرارَ</b> النوع.</p>' },
    { h: 'التمثيلُ بالخطوط', p: 57, html: '<p>يُستعملُ <b>التمثيلُ بالخطوط</b> لتوضيحِ تغيُّرِ مجموعةٍ من البياناتِ مع مرورِ الزمن. ومن ميلِ القطعِ المستقيمةِ الواصلةِ بينَ النقاط، يمكنُ وصفُ اتّجاهِ البياناتِ صعودًا أو هبوطًا.</p>' + chartBox(POP, { kind: 'line', title: 'عددُ سكّانِ الأرض (بالملايين)', step: 1000, x: 'العام (هـ)' }) },
    { h: '🧪 جرّبْ: ارسمْ بنفسِك', html: '<p class="meta">مثّلْ بياناتِ المحميّاتِ البرّيّة (المساحةُ بآلافِ كلم²).</p>', tool: el => graphMaker(el, { data: RES, kind: 'bar', title: 'بعضُ المحميّاتِ البرّيّةِ في المملكة', y: 'المساحة (بالآلاف كلم²)', cat: 'المحميّة', step: 2 }, ok => ok && star(1, 'رسمتَ تمثيلًا بالأعمدة')) }],
